    t = inp.split()
    if len(t) < 1:
        return False
    n = int(t[0])
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(t) != n + 1:
        return False
    a = [int(x) for x in t[1:]]
    return all(1 <= x <= 10**6 for x in a)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    a = [int(x) for x in t[1:1 + n]]
    res = []
    for i in range(n):
